WITH shipments AS ( SELECT s.s_store_sk, s.s_store_name, cd_closed.d_date AS closed_on, c.c_customer_sk, c.c_first_name, c.c_last_name, COUNT(ws.ws_order_number) AS shipments_cnt FROM store s LEFT JOIN date_dim cd_closed ON s.s_closed_date_sk = cd_closed.d_date_sk JOIN web_sales ws ON ws.ws_warehouse_sk = s.s_store_sk JOIN date_dim ship_date ON ws.ws_ship_date_sk = ship_date.d_date_sk JOIN customer c ON ws.ws_ship_customer_sk = c.c_customer_sk WHERE cd_closed.d_date IS NOT NULL AND ship_date.d_date > cd_closed.d_date GROUP BY s.s_store_sk, s.s_store_name, cd_closed.d_date, c.c_customer_sk, c.c_first_name, c.c_last_name ) SELECT sh.s_store_sk, sh.s_store_name, sh.closed_on, sh.c_customer_sk, sh.c_first_name, sh.c_last_name, sh.shipments_cnt, DENSE_RANK() OVER (PARTITION BY sh.s_store_sk ORDER BY sh.shipments_cnt DESC) AS customer_shipments_rank, RANK() OVER (ORDER BY sh.shipments_cnt DESC) AS global_shipments_rank FROM shipments sh ORDER BY sh.shipments_cnt DESC LIMIT 20
